DWORD packedColor(FXMVECTOR value, float alpha) { XMFLOAT4 f; XMStoreFloat4(&f,value); auto byte = [](float x) { return unsigned(std::clamp(x,0.f,1.f)*255+.5f); }; return (byte(alpha)<<24)|(byte(f.x)<<16)|(byte(f.y)<<8)|byte(f.z); }
